const RECUR_OPTIONS = [
  { value:"none",         label:"Does not repeat",      short:"" },
  { value:"daily",        label:"Daily",                short:"Daily" },
  { value:"weekly",       label:"Weekly",               short:"Weekly" },
  { value:"biweekly",     label:"Every 2 weeks",        short:"Bi-weekly" },
  { value:"monthly",      label:"Monthly",              short:"Monthly" },
  { value:"monthly_last", label:"Monthly (last day)",   short:"Month-end" },
  { value:"yearly",       label:"Yearly",               short:"Yearly" },
];

function nextRecurDeadline(rule, fromDate) {
  const d = new Date(fromDate);
  if      (rule==="daily")        d.setDate(d.getDate()+1);
  else if (rule==="weekly")       d.setDate(d.getDate()+7);
  else if (rule==="biweekly")     d.setDate(d.getDate()+14);
  else if (rule==="monthly")      d.setMonth(d.getMonth()+1);
  else if (rule==="monthly_last") d.setMonth(d.getMonth()+2, 0);
  else if (rule==="yearly")       d.setFullYear(d.getFullYear()+1);
  return d;
}

function recurDescription(rule, deadline) {
  if (!rule || rule==="none") return null;
  const next = nextRecurDeadline(rule, deadline);
  return `Next: ${next.toLocaleDateString("en-US",{weekday:"short",month:"short",day:"numeric"})}`;
}

