// ─── RICH TEXT ────────────────────────────────────────────────────────────────
const URL_RE = /(https?:\/\/[^\s<>"']+)/;
const MENTION_RE = /(@[\w][\w ]*)/;
const RichText = ({ text }) => {
  if (!text) return null;
  // Split on URLs FIRST (so @mention regex can't swallow "https"), then @mentions inside non-URL parts
  return (
    <span style={{ whiteSpace:"pre-wrap" }}>
      {text.split(URL_RE).map((chunk,i) =>
        chunk.match(/^https?:\/\//)
          ? <a key={i} href={chunk} target="_blank" rel="noopener noreferrer" style={{ color:"#2563eb", textDecoration:"underline", wordBreak:"break-all" }}>{chunk}</a>
          : <span key={i}>{chunk.split(MENTION_RE).map((seg,j) =>
              seg.startsWith("@")
                ? <span key={j} style={{ color:"#6366f1", fontWeight:700, background:"#eef2ff", borderRadius:4, padding:"0 3px" }}>{seg}</span>
                : seg
            )}</span>
      )}
    </span>
  );
};

// ─── MEDIA HELPERS ────────────────────────────────────────────────────────────
// Always upload to Drive. For images ≤500KB also keep a base64 thumbnail for
// inline preview without a round-trip. Videos / PDFs / docs → Drive ID only.
const THUMB_SIZE_LIMIT = 500 * 1024; // 500 KB

const readFileAsBase64 = (f) => new Promise((res) => {
  const r = new FileReader();
  r.onload = ev => res(ev.target.result);
  r.readAsDataURL(f);
});

// Upload a File object to a Drive folder, return Drive file metadata
const uploadFileToDrive = async (file, folderId, accessToken) => {
  const buildForm = () => {
    const meta = { name: file.name, parents: folderId ? [folderId] : [] };
    const f = new FormData();
    f.append("metadata", new Blob([JSON.stringify(meta)], { type: "application/json" }));
    f.append("file", file);
    return f;
  };
  const doUpload = async (token) => fetch(
    "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink",
    { method: "POST", headers: { Authorization: `Bearer ${token}` }, body: buildForm() }
  );
  let res = await doUpload(accessToken);
  if (!res.ok && res.status === 401) {
    // Token expired — on web we can't silently refresh, just throw so caller handles it
    throw new Error("Upload failed: session expired (401). Please sign in again.");
  }
  if (!res.ok) throw new Error(`Drive upload failed: ${res.status}`);
  const driveFile = await res.json();
  // Share as public reader so anyone can view via thumbnail URL
  try {
    await fetch(`https://www.googleapis.com/drive/v3/files/${driveFile.id}/permissions`, {
      method: "POST",
      headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ role: "reader", type: "anyone" })
    });
  } catch(e) {}
  return driveFile;
};

// Process picked files: upload to Drive, use blob URL for instant preview + Drive thumbnail for persistent display
const processFiles = async (files, folderId, accessToken) => {
  return Promise.all(Array.from(files).map(async (f) => {
    const base = { type: f.type, name: f.name, size: f.size };
    const blobUrl = f.type.startsWith("image/") ? URL.createObjectURL(f) : null;
    // Try Drive upload if we have credentials
    if (accessToken && folderId) {
      try {
        const driveFile = await uploadFileToDrive(f, folderId, accessToken);
        const entry = {
          ...base,
          driveId: driveFile.id,
          driveUrl: driveFile.webViewLink,
          imgUrl: `https://drive.google.com/thumbnail?id=${driveFile.id}&sz=w600`
        };
        if (blobUrl) entry.blobUrl = blobUrl;
        return entry;
      } catch (e) {
        console.warn("Drive upload failed:", e);
        return { ...base, uploadError: e.message || "Upload failed" };
      }
    }
    // Fallback: base64 (offline / no credentials) — only safe for small files
    const dataUrl = await readFileAsBase64(f);
    return { ...base, dataUrl };
  }));
};

