const buildEmail = (tasks, user, company) => {
  const rel    = tasks.filter(t => (Array.isArray(t.assignedTo)?t.assignedTo:[t.assignedTo]).includes(user.id) || t.createdBy === user.id);
  const missed = rel.filter(t => t.missedDeadline).length;
  const done   = rel.filter(t => t.status === "done").length;
  const prog   = rel.filter(t => t.status === "in_progress").length;
  return {
    subject:`[${company.name}] Task Progress${missed>0?` — ⚠️ ${missed} Missed`:""} · ${done} Done · ${prog} In Progress`,
    body:`Hi ${user.name},\n\nYour daily task summary from ${company.name}:\n\n✅ Completed: ${done}\n🔄 In Progress: ${prog}\n⚠️ Missed: ${missed}\n\nLog in to Tasks Therapy to review your tasks.\n\n— Tasks Therapy · ${company.name}`,
  };
};

