const ToastContainer = ({ toasts, onDismiss, onAction }) => {
  if (!toasts || toasts.length === 0) return null;
  return (
    <div style={{ position:"fixed", top:12, left:"50%", transform:"translateX(-50%)", width:"calc(100% - 32px)", maxWidth:460, zIndex:9999, display:"flex", flexDirection:"column", gap:8, pointerEvents:"none" }}>
      {toasts.map(t => {
        const bg = t.type === "error" ? "#fef2f2" : t.type === "success" ? "#f0fdf4" : "#eef2ff";
        const border = t.type === "error" ? "#fecaca" : t.type === "success" ? "#bbf7d0" : "#c7d2fe";
        const color = t.type === "error" ? "#dc2626" : t.type === "success" ? "#15803d" : "#4338ca";
        const icon = t.type === "error" ? "⚠️" : t.type === "success" ? "✅" : "🔔";
        return (
          <div key={t.id} style={{ pointerEvents:"auto", background:bg, border:`1px solid ${border}`, borderRadius:12, padding:"10px 14px", display:"flex", alignItems:"flex-start", gap:10, boxShadow:"0 4px 20px rgba(0,0,0,0.12)", fontFamily:"'Georgia',serif", animation:"slideDown 0.3s ease-out" }}>
            <span style={{ fontSize:18, flexShrink:0, lineHeight:1 }}>{icon}</span>
            <div style={{ flex:1, minWidth:0 }}>
              <p style={{ margin:0, fontSize:14, color, fontWeight:600, lineHeight:1.4 }}>{t.message}</p>
              {t.sub && <p style={{ margin:"2px 0 0", fontSize:12, color:"#64748b", lineHeight:1.3 }}>{t.sub}</p>}
            </div>
            {t.actionLabel && (
              <button onClick={()=>onAction(t)} style={{ background:color, border:"none", borderRadius:7, padding:"4px 10px", color:"white", fontSize:12, fontWeight:700, cursor:"pointer", fontFamily:"inherit", flexShrink:0, whiteSpace:"nowrap" }}>
                {t.actionLabel}
              </button>
            )}
            <button onClick={()=>onDismiss(t.id)} style={{ background:"none", border:"none", color:"#94a3b8", fontSize:16, cursor:"pointer", padding:"0 2px", flexShrink:0, lineHeight:1 }}>✕</button>
          </div>
        );
      })}
    </div>
  );
};

