        if (snap.users)    { setUsers(snap.users);       lsSet(LS.users,   snap.users);    }
        if (snap.cats)     { setCats(snap.cats);         lsSet(LS.cats,    snap.cats);     }
        if (snap.tasks)    { setTasks(snap.tasks);       lsSet(LS.tasks,   snap.tasks);    }
