                       <button onClick={()=>{const ws=workspaces.find(w=>w.id===activeWsId);if(ws?.sheetId&&gUser?.accessToken)fetch(`https://sheets.googleapis.com/v4/spreadsheets/${ws.sheetId}/values/Users`,{headers:{Authorization:`Bearer ${gUser.accessToken}`}}).then(r=>r.json()).then(d=>{const rows=d.values||[];if(rows.length>=2){const h=rows[0];const p=rows.slice(1).map(row=>{const o={};h.forEach((k,ii)=>{o[k]=row[ii]||"";}); if("pending" in o)o.pending=o.pending===true||o.pending==="true"||o.pending==="TRUE"; return o;}); mergeUsersFromSheet(p);}}).catch(()=>{});}} style={{fontSize:11,padding:"2px 8px",background:"#f1f5f9",border:"1px solid #e2e8f0",borderRadius:5,cursor:"pointer",color:"#64748b",fontFamily:"inherit"}}>↺</button>
